/* Hand-written RV32I leaves. a0=state, a1=remaining (rubik_asm_search_bound).
 * Preserve every callee-saved register; no calls, multiply, divide, or CSR.
 * state_t layout: seven permutation bytes followed by seven orientation bytes.
 */
    .text
    .align 2
    .globl rubik_asm_endgame_lookup
    .type rubik_asm_endgame_lookup,@function
rubik_asm_endgame_lookup:
    /* Full-state 30-bit key: six 5-bit (permutation,orientation) pairs. */
    lbu a3,0(a0)
    lbu a4,7(a0)
    slli a3,a3,2
    or a3,a3,a4
    .macro KEY_PAIR p,o
    lbu a4,\p(a0)
    lbu a5,\o(a0)
    slli a3,a3,5
    slli a4,a4,2
    or a4,a4,a5
    or a3,a3,a4
    .endm
    KEY_PAIR 1,8
    KEY_PAIR 2,9
    KEY_PAIR 3,10
    KEY_PAIR 4,11
    KEY_PAIR 5,12
    .purgem KEY_PAIR

    mv t0,a3
    slli t1,t0,13
    xor t0,t0,t1
    srli t1,t0,17
    xor t0,t0,t1
    slli t1,t0,5
    xor t0,t0,t1
    srli t5,t0,14
    ori t5,t5,1
    slli t5,t5,2
    slli t0,t0,18
    srli t0,t0,16
    la t1,rubik_asm_endgame_keys
    li t2,-1
.Lhash_probe:
    add t3,t1,t0
    lw t4,0(t3)
    beq t4,a3,.Lhash_hit
    beq t4,t2,.Lhash_miss
    add t0,t0,t5
    slli t0,t0,16
    srli t0,t0,16
    j .Lhash_probe
.Lhash_hit:
    srli a0,t0,2
    ret
.Lhash_miss:
    li a0,-1
    ret
    .size rubik_asm_endgame_lookup,.-rubik_asm_endgame_lookup

    /* Append one ternary digit to an index; constants expand at assembly. */
    .macro TERNARY offset,base
    lbu a3,\offset(\base)
    slli a4,a2,1
    add a2,a2,a4
    add a2,a2,a3
    .endm
    .align 2
    .globl rubik_asm_search_bound
    .type rubik_asm_search_bound,@function
rubik_asm_search_bound:
    lbu t0,0(a0)
    lbu t1,1(a0)
    lbu t2,2(a0)
    lbu t3,3(a0)
    lbu t4,4(a0)
    lbu t5,5(a0)
    lbu t6,6(a0)
    /* Lehmer digit 0 is p0. Digit 1 = p1 - count(earlier < p1).
     * Digit 2 uses two earlier comparisons; later digits use the suffix.
     * Nine comparisons total instead of nested loops with 21 comparisons.
     */
    slli a2,t0,1
    add a2,a2,t0
    slli a2,a2,1
    sltu a3,t0,t1
    sub a3,t1,a3
    add a2,a2,a3
    /* radix 5 and digit 2 */
    slli a4,a2,2
    add a2,a2,a4
    sltu a3,t0,t2
    sltu a4,t1,t2
    add a3,a3,a4
    sub a3,t2,a3
    add a2,a2,a3
    /* radix 4 and digit 3 */
    slli a2,a2,2
    sltu a3,t4,t3
    sltu a4,t5,t3
    add a3,a3,a4
    sltu a4,t6,t3
    add a3,a3,a4
    add a2,a2,a3
    /* radix 3 and digit 4 */
    slli a4,a2,1
    add a2,a2,a4
    sltu a3,t5,t4
    sltu a4,t6,t4
    add a3,a3,a4
    add a2,a2,a3
    /* radix 2 and digit 5; final radix 1 adds zero */
    slli a2,a2,1
    sltu a3,t6,t5
    add a2,a2,a3
    la a7,rubik_asm_compact_perm_dist
    add a3,a7,a2
    lbu a6,0(a3)

    lbu a2,7(a0)
    TERNARY 8,a0
    TERNARY 9,a0
    TERNARY 10,a0
    TERNARY 11,a0
    TERNARY 12,a0
    la a7,rubik_asm_compact_orient_dist
    add a3,a7,a2
    lbu a3,0(a3)
    bge a6,a3,.Lasm_forward_max
    mv a6,a3
.Lasm_forward_max:
    /* Forward-only ablation: a1=remaining is intentionally unused.
     * The caller compares this admissible bound to the remaining budget. */
    mv a0,a6
    ret
    .size rubik_asm_search_bound,.-rubik_asm_search_bound
    .purgem TERNARY
    .text



