rubik_asm_bloom6_maybe:
    /* Full-state 30-bit key: six 5-bit (permutation,orientation) pairs. */
    lbu a3,0(a0)
    lbu a4,7(a0)
    slli a3,a3,2
    or a3,a3,a4
    .macro KEY_PAIR p,o
    lbu a4,\p(a0)
