    slli a3,a3,5
    slli a4,a4,2
    or a4,a4,a5
    or a3,a3,a4
    .endm
    KEY_PAIR 1,8
    KEY_PAIR 2,9
    KEY_PAIR 3,10
    KEY_PAIR 4,11
    KEY_PAIR 5,12
    .purgem KEY_PAIR

    slli t0,a3,13
    xor a3,a3,t0
    srli t0,a3,17
    xor a3,a3,t0
    slli t0,a3,5
    xor a3,a3,t0
    srli t1,a3,16
    ori t1,t1,1
    la t2,rubik_asm_bloom6_bits
