    beq t3,zero,bloom6_reject
    add a3,a3,t1
    add t2,t2,t6
    slli t3,a3,16
    srli t3,t3,19
    add t3,t2,t3
    lbu t3,0(t3)
    andi t5,a3,7
    srl t3,t3,t5
    andi t3,t3,1
    beq t3,zero,bloom6_reject
bloom6_accept:
    li a0,1
